        TileEntityAnimatedScreenSelector freshOriginal=(TileEntityAnimatedScreenSelector)com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.createTileEntity(null,com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR.getDefaultState());NBTTagCompound factory=freshOriginal.writeToNBT(new NBTTagCompound());factory.merge(picked);freshOriginal.readFromNBT(factory);freshOriginal.initializeDisplayArtwork(com.vandorlabs.blocks.ModBlocks.ANIMATED_SCREEN_SELECTOR);require(freshOriginal.frameAppearance.front==-1,"vanilla ItemBlock merge restored the factory frame over Original selection");
        for(String id:new String[]{"analysis_framed_gas_giant","analysis_framed_ice_planet","analysis_framed_surface_map","analysis_framed_terrestrial"}){
            require(TileEntityAnimatedScreenSelector.isValidInputPanel(id),"legacy analysis input fixture exists");NBTTagCompound legacy=new TileEntityAnimatedScreenSelector().writeToNBT(new NBTTagCompound());legacy.setString("inputPanel",id);TileEntityAnimatedScreenSelector input=new TileEntityAnimatedScreenSelector();input.readFromNBT(legacy);require(input.getInputPanel().equals(id)&&input.frameAppearance.front==bolted,"unpaired previous-release input artwork was replaced");
            int legacyChoice=com.vandorlabs.tiles.ScreenHousingTextures.screenIndex("console_inputs/"+id+"_static");require(legacyChoice>0,"legacy unified analysis artwork exists");NBTTagCompound surface=new NBTTagCompound();surface.setInteger("PrimarySurfaceTexture",legacyChoice);require(FrameAppearance.migrateLegacyScreen(surface)&&surface.getInteger("PrimarySurfaceTexture")==legacyChoice&&surface.getInteger("FrameFront")==bolted,"unpaired unified artwork migration lost its source or frame");
            input.frameAppearance.artworkVersion=1;input.frameAppearance.front=-1;TileEntityAnimatedScreenSelector originalInput=new TileEntityAnimatedScreenSelector();originalInput.readFromNBT(input.writeToNBT(new NBTTagCompound()));require(originalInput.getInputPanel().equals(id)&&originalInput.frameAppearance.front==-1,"unpaired input Original frame selection did not persist");
        }
        HousingTextureList splitPicker=HousingTextureList.forCategory("Screens",0,0,160,0);try{java.lang.reflect.Field f=HousingTextureList.class.getDeclaredField("options");f.setAccessible(true);for(Object row:((java.util.Map<?,?>)f.get(splitPicker)).values()){HousingTextureList.Option option=(HousingTextureList.Option)row;require(FrameAppearance.bareChoice(option.choice)==option.choice,"paired framed artwork leaked into split selector");}}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}
        screen.frameAppearance.bare=true;screen.frameAppearance.interior=bolted;screen.frameAppearance.split=true;screen.frameAppearance.splitTop=0;screen.frameAppearance.splitBottom=1;screen.frameAppearance.displayFit=true;
        TileEntityAnimatedScreenSelector copy=new TileEntityAnimatedScreenSelector();copy.readFromNBT(screen.writeToNBT(new NBTTagCompound()));require(copy.frameAppearance.bare&&copy.frameAppearance.front==bolted&&copy.frameAppearance.interior==bolted&&copy.frameAppearance.split&&copy.frameAppearance.splitTop==0&&copy.frameAppearance.splitBottom==1&&copy.frameAppearance.displayFit,"frame/split tile persistence");
        com.vandorlabs.network.MessageFrameAppearance packet=new com.vandorlabs.network.MessageFrameAppearance(screen,screen.frameAppearance);io.netty.buffer.ByteBuf bytes=io.netty.buffer.Unpooled.buffer();packet.toBytes(bytes);require(bytes.readableBytes()==32,"fixed frame packet size including optional Bare flag");com.vandorlabs.network.MessageFrameAppearance decoded=new com.vandorlabs.network.MessageFrameAppearance();decoded.fromBytes(bytes);io.netty.buffer.ByteBuf round=io.netty.buffer.Unpooled.buffer();decoded.toBytes(round);bytes.readerIndex(0);require(bytes.equals(round),"frame packet roundtrip");io.netty.buffer.ByteBuf legacy=bytes.copy(0,27),legacyRound=io.netty.buffer.Unpooled.buffer();com.vandorlabs.network.MessageFrameAppearance oldPacket=new com.vandorlabs.network.MessageFrameAppearance();oldPacket.fromBytes(legacy);oldPacket.toBytes(legacyRound);require(legacyRound.readableBytes()==32&&!legacyRound.getBoolean(27),"old frame packet did not default to visible front");require(bytes.slice(0,27).equals(legacyRound.slice(0,27)),"optional Bare flag changed legacy frame packet fields");legacy.release();legacyRound.release();bytes.release();round.release();
        NBTTagCompound legacyGlass=new NBTTagCompound();legacyGlass.setInteger("FrameInterior",bolted);FrameAppearance oldGlass=new FrameAppearance();oldGlass.read(legacyGlass);require(oldGlass.exteriorChoice()==bolted,"legacy exterior must retain its previous interior finish");NBTTagCompound preserved=new NBTTagCompound();oldGlass.write(preserved);require(!preserved.hasKey("FrameExterior"),"legacy absent exterior was rewritten");
        oldGlass.exterior=oldGlass.exteriorChoice();oldGlass.interior=-1;NBTTagCompound independent=new NBTTagCompound();oldGlass.write(independent);FrameAppearance restored=new FrameAppearance();restored.read(independent);require(restored.interior==-1&&restored.exteriorChoice()==bolted,"first Interior change altered legacy Exterior");
        glass.frameAppearance.read(independent);TileEntityProgrammableGlass glassRound=new TileEntityProgrammableGlass();glassRound.readFromNBT(glass.writeToNBT(new NBTTagCompound()));require(glassRound.frameAppearance.interior==-1&&glassRound.frameAppearance.exteriorChoice()==bolted,"independent glass sides lost on tile roundtrip");
        int materialA=-1,materialB=-1;
        for(int i=0;i<ScreenHousingTextures.IDS.length;i++)if(ScreenHousingTextures.visible(i)&&ScreenHousingTextures.generalTexture(i)){
            if(materialA<0)materialA=ScreenHousingTextures.choiceAt(i);else{materialB=ScreenHousingTextures.choiceAt(i);break;}
        }
        require(materialA>=0&&materialB>=0,"two ordinary material finish fixtures");
        glass.frameAppearance.interior=materialA;glass.frameAppearance.exterior=materialB;
        glassRound.readFromNBT(glass.writeToNBT(new NBTTagCompound()));
        require(glassRound.frameAppearance.interior==materialA&&glassRound.frameAppearance.exteriorChoice()==materialB,"general Interior/Exterior lost through tile save");
        io.netty.buffer.ByteBuf materialBytes=io.netty.buffer.Unpooled.buffer();
        new com.vandorlabs.network.MessageFrameAppearance(glass,glass.frameAppearance).toBytes(materialBytes);
        com.vandorlabs.network.MessageFrameAppearance materialPacket=new com.vandorlabs.network.MessageFrameAppearance();materialPacket.fromBytes(materialBytes);materialBytes.release();
        io.netty.buffer.ByteBuf materialRound=io.netty.buffer.Unpooled.buffer();materialPacket.toBytes(materialRound);
        require(materialRound.getInt(12)==materialA&&materialRound.getInt(28)==materialB&&FrameAppearance.validSurface(materialA)&&FrameAppearance.validSurface(materialB),"general finishes lost or refused in packet roundtrip");materialRound.release();
        for(com.vandorlabs.render.ScreenSurface.Kind kind:com.vandorlabs.render.ScreenSurface.Kind.values()){com.vandorlabs.render.ScreenSurface.Quad full=com.vandorlabs.render.ScreenSurface.quad(kind,false),top=com.vandorlabs.render.ScreenSurface.half(full,true),bottom=com.vandorlabs.render.ScreenSurface.half(full,false);require(top.bottomLeft.y==bottom.topLeft.y&&top.bottomLeft.z==bottom.topLeft.z,"split display gap");require(top==com.vandorlabs.render.ScreenSurface.half(full,true),"split geometry allocates repeatedly");}
        try{
            HousingTextureList picker=HousingTextureList.forFrames(0,0,160,-1,8);
            java.lang.reflect.Field rows=HousingTextureList.class.getDeclaredField("rows"),scroll=HousingTextureList.class.getDeclaredField("scroll"),count=HousingTextureList.class.getDeclaredField("count");rows.setAccessible(true);scroll.setAccessible(true);count.setAccessible(true);
            int originalRow=((java.util.List<?>)rows.get(picker)).indexOf(-1);require(originalRow>=1,"Original artwork has a distinct row from the Frame category");scroll.setInt(picker,Math.max(0,originalRow-count.getInt(picker)+1));
            require(picker.click(4,(1+originalRow-scroll.getInt(picker))*HousingTextureList.ROW_HEIGHT+4,0)&&picker.picked()&&picker.selected()==-1,"actual Original artwork click selects the default instead of toggling the category");
        }catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}
